  ["%s %s"] = "%s %s",
  ["|cffffd100Prices:|r GoldScout Companion keeps your auction house's prices up to date every hour."] = "|cffffd100Preise:|r GoldScout Companion hält die Preise deines Auktionshauses jede Stunde aktuell.",
  ["|cffffd100Prices:|r from your own auction house scan. For fresh prices every hour without scanning, get the free GoldScout Companion:"] = "|cffffd100Preise:|r aus deinem eigenen AH-Scan. Für stündlich frische Preise ohne Scannen hol dir den kostenlosen GoldScout Companion:",
  ["|cffffd100Prices:|r regional estimates for now, so the Farm list works right away. For your own auction house's prices, get the free GoldScout Companion, or press Scan AH at an auctioneer:"] = "|cffffd100Preise:|r vorerst regionale Schätzungen, damit die Farm-Liste sofort funktioniert. Für die Preise deines eigenen Auktionshauses hol dir den kostenlosen GoldScout Companion oder drücke bei einem Auktionator AH scannen:",
  ["|cffffd100Prices:|r get the free GoldScout Companion for your auction house's prices every hour, or press Scan AH at any auctioneer:"] = "|cffffd100Preise:|r Hol dir den kostenlosen GoldScout Companion für stündliche Preise deines Auktionshauses, oder drücke bei einem Auktionator AH scannen:",
  ["|cffffd100Recipes:|r learned. The Craft tab ranks what you can make."] = "|cffffd100Rezepte:|r gelernt. Der Reiter Herstellen zeigt, was du herstellen kannst, nach Gewinn sortiert.",
  ["|cffffd100Recipes:|r open each of your profession windows once, so the Craft tab can rank what you make."] = "|cffffd100Rezepte:|r Öffne jedes Berufsfenster einmal, damit der Reiter Herstellen deine Rezepte bewerten kann.",
  ["|cffffd100Farm:|r pick a row on the Farm tab and press Hunt for a waypoint, mob markers and a gold-per-hour tracker."] = "|cffffd100Farmen:|r Wähle im Reiter Farmen eine Zeile und drücke Jagen für Wegpunkt, Mob-Markierungen und eine Anzeige für Gold pro Stunde.",
