  ["none yet"] = "noch keine",
  ["%d kills recorded by GoldScout players, yours included. %d more and its drop rates are solid."] = "%d Kills von GoldScout-Spielern erfasst, deine eingeschlossen. Noch %d, dann sind die Dropraten verlässlich.",
  ["Most common drop: %s (%d%% of kills)."] = "Häufigste Beute: %s (%d%% der Kills).",
  ["Select it and press Hunt for a waypoint and to count your kills. Share your loot with GoldScout Companion so every player's rates get better."] = "Wähle ihn aus und drücke Jagen für einen Wegpunkt und um deine Kills zu zählen. Teile deine Beute mit GoldScout Companion, damit die Raten für alle Spieler besser werden.",
  ["Data wanted"] = "Daten gesucht",
  ["Mobs that need more kills before their drop rates are solid, near your level and in your zone first. Hunt one and share your loot: every GoldScout player's rates get better."] = "Gegner, die mehr Kills brauchen, bevor ihre Dropraten verlässlich sind; nahe deiner Stufe und in deinem Gebiet zuerst. Jage einen und teile deine Beute: Die Raten werden für alle GoldScout-Spieler besser.",
  ["Kills wanted: %s needs %d more for solid drop rates."] = "Kills gesucht: %s braucht noch %d für verlässliche Dropraten.",
  ["Every mob players have recorded near your level has solid drop rates. Try 'All levels'."] = "Alle erfassten Gegner nahe deiner Stufe haben verlässliche Dropraten. Probiere 'Alle Stufen'.",
  ["  /gscout wanted - mobs that need more kills for solid drop rates"] = "  /gscout wanted - Gegner, die mehr Kills für verlässliche Dropraten brauchen",
