  ["Dropped in %d of %d kills."] = "Bei %d von %d Kills gedroppt.",
  ["Per kill"] = "Pro Kill",
  ["On the website:"] = "Auf der Website:",
  ["Nobody has recorded loot from this mob yet. Kill it a few times and share your loot to add it."] = "Noch hat niemand Beute von diesem Gegner erfasst. Töte ihn ein paar Mal und teile deine Beute, um sie hinzuzufügen.",
  ["%d kills recorded by GoldScout players, %d of them yours."] = "%d Kills von GoldScout-Spielern erfasst, %d davon von dir.",
  ["%d kills recorded by GoldScout players."] = "%d Kills von GoldScout-Spielern erfasst.",
  ["That's only a few, so these rates are a rough guide."] = "Das sind erst wenige, die Raten sind also nur ein grober Anhaltspunkt.",
  ["Players have killed it, but it hasn't dropped any items yet."] = "Spieler haben ihn getötet, aber er hat noch keine Gegenstände gedroppt.",
  ["Loot averages %s per kill, counting items seen at least %d times. Coin isn't recorded."] = "Beute im Schnitt %s pro Kill, gezählt werden Gegenstände, die mindestens %d-mal gefunden wurden. Münzen werden nicht erfasst.",
  ["Target a mob first, then try again."] = "Wähle zuerst einen Gegner als Ziel aus und versuch es dann erneut.",
  ["Drop rates"] = "Dropraten",
  ["  /gscout drops - everything your target drops (or right-click its portrait)"] = "  /gscout drops - alles, was dein Ziel droppt (oder Rechtsklick auf sein Porträt)",
  ["GoldScout: vendors won't buy it, but it sells on the auction house. List it."] = "GoldScout: Händler kaufen es nicht, aber im Auktionshaus verkauft es sich. Stell es ein.",
  ["GoldScout: worth %s each on the auction house, %s at a vendor. List it."] = "GoldScout: im Auktionshaus %s pro Stück wert, beim Händler %s. Stell es ein.",
  ["Mark bag items worth listing on the auction house"] = "Taschengegenstände markieren, die sich im Auktionshaus lohnen",
  ["An auction house hammer on crafting reagents and green or better items that sell for at least double their vendor price on your auction house, after the cut. Needs your own prices: a scan, or GoldScout Companion."] = "Ein Auktionshammer auf Handwerksmaterialien und grünen oder besseren Gegenständen, die sich in deinem Auktionshaus nach Abzug der Gebühr für mindestens das Doppelte des Händlerpreises verkaufen. Braucht deine eigenen Preise: einen Scan oder GoldScout Companion.",
  ["Flip"] = "Handel",
  ["Margin"] = "Marge",
  ["Stock"] = "Bestand",
  ["Buy at Blackwater, each"] = "Kauf bei Schwarzwasser, je",
  ["Sells for here, each"] = "Verkauf hier, je",
  ["Profit each"] = "Gewinn je",
  ["%d listed at Blackwater, %d on your auction house."] = "%d bei Schwarzwasser eingestellt, %d in deinem Auktionshaus.",
  ["Only the cheapest auctions are at this price: check before buying many. Prices seen %s."] = "Nur die billigsten Auktionen kosten so wenig: schau nach, bevor du viele kaufst. Preise gesehen %s.",
  ["Best flip: buy %s at Blackwater for %s, sell it here for %s: %s profit each."] = "Bester Handel: %s bei Schwarzwasser für %s kaufen, hier für %s verkaufen: %s Gewinn je Stück.",
  ["Your character has no faction, so there's no other auction house to sell on."] = "Dein Charakter hat keine Fraktion, also gibt es kein anderes Auktionshaus zum Verkaufen.",
  ["No Blackwater prices yet: GoldScout Companion saves them every hour, or scan at a Blackwater auction house."] = "Noch keine Schwarzwasser-Preise: GoldScout Companion speichert sie stündlich, oder scanne in einem Schwarzwasser-Auktionshaus.",
  ["No flips right now: nothing at Blackwater sells for at least 15% more on your auction house after the cut."] = "Gerade kein Handel: nichts von Schwarzwasser bringt in deinem Auktionshaus nach Abzug mindestens 15 % mehr.",
  ["  /gscout farm | craft | flip - open a tab"] = "  /gscout farm | craft | flip - einen Reiter öffnen",
  ["Working out the best farms..."] = "Die besten Farmen werden ermittelt ...",
  ["Show dungeon drops"] = "Dungeon-Beute zeigen",
  ["Also list farms on mobs inside dungeons and raids. You run those with a group and a lockout, so their gold per hour doesn't compare with farming on your own."] = "Auch Farmen an Gegnern in Dungeons und Schlachtzügen zeigen. Die läufst du mit einer Gruppe und einer Sperre, ihr Gold pro Stunde ist also nicht mit Farmen allein vergleichbar.",
  ["Long shots"] = "Risiko-Flips",
  ["Also list flips that sell here for over %d times the item's usual price in your region, after the others. Some are real gaps between the factions; many are one listing nobody will buy."] = "Auch Flips zeigen, die hier für mehr als das %d-Fache des üblichen Preises in deiner Region verkauft werden, nach den anderen. Manche sind echte Unterschiede zwischen den Fraktionen, viele nur ein Angebot, das niemand kauft.",
  ["Long shot: it usually sells for about %s in your region. A price far above that may never sell: check how many are listed before buying."] = "Risiko-Flip: In deiner Region kostet es meist etwa %s. Ein Preis weit darüber wird vielleicht nie bezahlt: Prüf vor dem Kauf, wie viele angeboten werden.",
})
